# DK SMM.  Sønderborg - Mommark Færge
#
let sm = path("d3.dk.smm");

with detail = 3, railway = :first :pax :removed {
    # point.dk.Sønderborg  dk.SBT

    with link = "line.dk.SMM" {
        track(:station, sm[:son.ym, :son.a]);
        track(sm[:son.a - 0.1dl, :sob - 0.49sw]);
    }

    with link = "point.dk.Sønderborg-By", railway = :station {
        track(sm[:sob - 0.5sw, :sob + 0.5sw]);
        marker(:left :de.bf, sm[:sob] << 0.5mt);
        slabel(:bottom, sm[:sob] >> 0.5mt + (-5dt, 0.3dt),
            "Sønderborg By"
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:sob + 0.49sw, :sob + 1.36km]);
        line_label(:right:nw, sm[:sob + 1.35km] >> 0.5mt, "SMM");
        track(sm[:sob + 1.34km, :sun - 0.49sw]);
    }

    with link = "point.dk.Sundsmark", railway = :station {
        track(sm[:sun - 0.5sw, :sun + 0.5sw]);
        marker(:left :de.hp, sm[:sun] << 0.5mt);
        slabel(:nw, sm[:sun] >> 0.5mt + (1dt, -0.8dt), 
            "Sundsmark"
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:sun + 0.49sw, :spa - 0.49sw]);
    }

    with link = "point.dk.Spang", railway = :station {
        track(sm[:spa - 0.5sw, :spa + 0.5sw]);
        marker(:left :de.hp, sm[:spa] << 0.5mt);
        slabel(:left, sm[:spa] << 0.5mt << 1sh + (-1.5dt, 0.3dt), 
            "Spang"
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:spa + 0.49sw, :vol.yv]);
        track(sm[:vol.yv, :vol - 0.49sw]);
    }

    with link = "point.dk.Vollerup", railway = :station {
        track(sm[:vol - 0.5sw, :vol + 0.5sw]);
        with layer = 1 marker(:left :de.bf :casing, sm[:vol] << 0.5mt);
        slabel(:top :bold, sm[:vol] >> 0.5mt + (0dt, -0.3km) + (-4.5dt, -1.5dt),
            "Vollerup"
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:vol + 0.49sw, :vol + 1.21km]);
        line_label(:right:n, sm[:vol + 1.2km] >> 0.5mt, (0.8dt, 0dt), "SMM");
        track(sm[:vol + 1.19km, :vol.yo - 0.99seg]);
        track(:station, sm[:vol.yo - 1seg, :vol.yo + 0.1dl]);
        track(sm[:vol.yo, :kir - 0.49sw]);
    }

    with link = "point.dk.Kirke-Hørup", railway = :station {
        track(sm[:kir - 0.5sw, :kir + 0.5sw]);
        marker(:left :de.hp, sm[:kir] << 0.5mt);
        marker(:left :de.exbf, sm[:kir] << 0.5mt);
        slabel(:top, sm[:kir] << 0.5mt << 1.4sh << 0.3dt,
            vbox(:center:bottom, " Kirke-", "Hørup")
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:kir + 0.49sw, :maj - 0.49sw]);
    }

    with link = "point.dk.Majbøl", railway = :station {
        track(sm[:maj - 0.5sw, :maj + 0.5sw]);
        marker(:left :de.hp, sm[:maj] << 0.5mt);
        slabel(:top, sm[:maj] << 0.5mt << 1sh << 0.3dt,
            "Majbøl"
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:maj + 0.49sw, :maj.yo]);
        track(sm[:maj.yo - 0.1dl, :ota - 0.49sw]);
    }

    with link = "point.dk.Over-Tandslet", railway = :station {
        track(sm[:ota - 0.5sw, :ota + 0.5sw]);
        with layer = 1 marker(:left :de.bf :casing, sm[:ota] << 0.5mt);
        slabel(:bottom, sm[:ota] >> 0.5mt + (-0.5dt, 0.5dt),
            vbox(:center:top, " Over-", "Tandslet")
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:ota + 0.49sw, :nta.yt + 0.1dl]);
    }

    with link = "point.dk.Neder-Tandslet", railway = :station {
        track(sm[:nta.yt, :nta + 0.5sw]);
        marker(:left :de.bf, sm[:nta] << 0.5mt);
        slabel(:right, sm[:nta] << 0.5mt << 1sh + (1.1dt, 0.5dt),
            vbox(:left:base, "Neder-", "Tandslet")
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:nta + 0.49sw, :lmo - 0.49sw]);
    }

    with link = "point.dk.Lille-Mommark", railway = :station {
        track(sm[:lmo - 0.5sw, :lmo.ys]);
        marker(:right :de.hp, sm[:lmo] >> 0.5mt);
        marker(:right :de.exbf, sm[:lmo] >> 0.5mt);
        slabel(:left, sm[:lmo] >> 0.5mt >> 1.4sh + (-2dt, 1dt),
            span(:bold, "Lille-Mommark")
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:lmo.ys - 0.1dl, :sar - 0.49sw]);
    }

    with link = "point.dk.Sarup", railway = :station {
        track(sm[:sar - 0.5sw, :sar + 0.5sw]);
        marker(:right :de.hp, sm[:sar] >> 0.5mt);
        slabel(:bottom, sm[:sar] >> 0.5mt >> 1sh + (0.5dt, 0.2dt),
            "Sarup"
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:sar + 0.49sw, :sar + 0.86km]);
        line_label(:right:w, sm[:sar + 0.85km] >> 0.5mt, "SMM");
        line_label(:left:e, sm[:sar + 0.85km] << 0.5mt,
            span(:former, "LMM")
        );
        track(sm[:sar + 0.84km, :mof - 0.49sw]);
    }

    with link = "point.dk.Mommark-Færgegård", railway = :station {
        track(sm[:mof - 0.5sw, :mof + 0.5sw]);
        marker(:right :de.hp, sm[:mof] >> 0.5mt);
        slabel(:right, sm[:mof] >> 0.5mt >> 1sh + (1dt, 1.1dt),
            "Mommark Færgegård"
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:mof + 0.49sw, :mom - 0.49sw]);
    }

    with link = "point.dk.Mommark-Færge", railway = :station {
        track(sm[:mom - 0.5sw, :mom + 0.5sw]);
        marker(:right :de.bf, sm[:mom] >> 0.5mt);
        slabel(:right, sm[:mom] >> 0.5mt >> 1sh + (1.2dt, 1.1dt),
            span(:bold, "Mommark Færge")
        );
    }
}

